// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether via fallback (owner call)
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        assertTrue(success);

        // Now a non-owner (address(1)) tries to withdrawAll
        address nonOwner = address(1);
        vm.deal(nonOwner, 0); // no ether needed for gas
        vm.prank(nonOwner);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        // The REFERENCE (correct) version reverts because msg.sender != owner, so ok == false.
        // The BUGGY version allows it, so ok == true, and the balance goes to address(1).
        // We assert the reference behavior: call reverts (ok == false).
        assertTrue(!ok);
    }
}

