pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Sequence:
        // 1. Owner deposits 1 ether via fallback (sends to contract).
        // 2. Owner sends 0.5 ether to a target via sendMoney.
        // 3. Owner calls withdrawAll to withdraw remaining balance.
        // After these, check owner's balance.

        address owner = address(this); // test contract is owner
        address target = address(0x1234);

        // Step 1: deposit 1 ether via fallback
        vm.deal(owner, 5 ether);
        vm.prank(owner);
        (bool ok1,) = address(c).call{value: 1 ether}("");
        assertTrue(ok1);

        // Step 2: send 0.5 ether to target
        vm.prank(owner);
        c.sendMoney(target, 0.5 ether);

        // Step 3: withdrawAll
        vm.prank(owner);
        c.withdrawAll();

        // After withdrawal, contract balance should be 0.
        // Reference version: after deposit(1) - send(0.5) = 0.5 remains, withdrawAll sends 0.5 to owner.
        // Buggy version: withdraw(_value) uses address(this).balance instead of _value,
        // but withdrawAll calls withdraw(address(this).balance) — that's the same quantity, so withdrawAll should still work correctly?
        // Actually the bug is in withdraw: it sends address(this).balance instead of _value.
        // But withdrawAll calls withdraw(address(this).balance) — so that argument equals the balance, so no difference.
        // However, if someone calls withdraw directly with a different amount, bug appears.
        // Let's test a different scenario: after deposit of 2 ether, owner calls withdraw(1 ether).
        // Reference: sends 1 ether to owner, contract keeps 1 ether.
        // Buggy: sends address(this).balance = 2 ether to owner, so owner gets 2 ether, contract gets 0.

        // Reset contract
        c = new C();
        owner = address(this);

        // Deposit 2 ether
        vm.deal(owner, 10 ether);
        vm.prank(owner);
        (ok1,) = address(c).call{value: 2 ether}("");
        assertTrue(ok1);

        // Owner calls withdraw(1 ether)
        vm.prank(owner);
        // This call will succeed in reference (sends 1 ether) but in buggy version sends 2 ether
        bool ok;
        try c.withdraw(1 ether) { ok = true; } catch { ok = false; }
        assertTrue(ok);

        // Now check contract balance:
        // Reference: 2 - 1 = 1 ether remains
        // Buggy: 2 - 2 = 0 ether remains
        assertEq(address(c).balance, 1 ether);
    }
}

