pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner deposits 1 ether via fallback
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        (bool ok1,) = address(c).call{value: 1 ether}("");
        assertTrue(ok1);

        // Owner deposits another 1 ether via fallback
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        (bool ok2,) = address(c).call{value: 1 ether}("");
        assertTrue(ok2);

        // Owner calls withdrawAll – should withdraw only 1 ether in reference?
        // Wait, we need a scenario where the versions diverge.
        // Let's reset: first deposit 1 ether, then call withdrawAll directly.
        // To isolate: deploy fresh, owner deposits 1 ether, then withdrawAll.
        // But cannot redeploy in test. Use two distinct accounts?
        // Simpler: after setUp, owner is this test contract.
        // Deposit 1 ether via fallback.
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool ok3,) = address(c).call{value: 1 ether}("");
        assertTrue(ok3);

        // Now call withdrawAll. Reference: withdraw(address(this).balance) which is 1 ether.
        // Buggy: withdraw(payable(msg.sender).transfer(address(this).balance)) – wrong param.
        // After withdrawAll, contract balance should be 0 in reference, but buggy uses address(this).balance as value to transfer,
        // which is the full balance, but transfers only that amount, so also 0. Actually both set balance to 0.
        // Need divergence in some observable state.
        // Second version depositCount increments once, same. Both withdrawAll succeed.
        // Actually the bug is that withdraw(payable(msg.sender).transfer(address(this).balance));
        // It calls withdraw with a value argument, but the function withdraw uses that value to transfer.
        // In reference: transfer(_value). In bug: transfer(address(this).balance) regardless of _value.
        // So if _value differs from address(this).balance, the bug sends the full balance instead of _value.
        // Scenario: owner deposits 2 ether, then someone else deposits 1 ether via fallback (so contract has 3 ether).
        // Owner calls withdraw(1 ether). Reference: sends 1 ether to owner, leaves 2 ether in contract.
        // Bug: sends address(this).balance = 3 ether to owner, leaving 0.
        // Observable: after withdraw, address(c).balance differs.
        vm.deal(address(this), 3 ether);
        vm.prank(address(this));
        (bool ok4,) = address(c).call{value: 2 ether}("");
        assertTrue(ok4);

        // Now another account deposits 1 ether
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        (bool ok5,) = address(c).call{value: 1 ether}("");
        assertTrue(ok5);

        // Owner withdraws 1 ether
        vm.prank(address(this));
        bool ok6;
        try c.withdraw(1 ether) { ok6 = true; } catch { ok6 = false; }
        assertTrue(ok6);

        // Now reference: contract balance should be 2 ether (3-1). Bug: 0 ether.
        assertEq(address(c).balance, 2 ether);
    }
}

